from __future__ import annotations

import csv
from dataclasses import dataclass
from pathlib import Path

from PIL import Image


SUPPORTED_EXTENSIONS = {".jpg", ".jpeg", ".png"}


@dataclass(frozen=True)
class ImageRecord:
    subject_id: str
    eye: str
    image_path: str
    width: int
    height: int
    format: str
    file_size: int


@dataclass(frozen=True)
class AnomalyRecord:
    subject_id: str
    eye: str
    image_path: str
    issue: str


@dataclass(frozen=True)
class SubjectScan:
    subject_id: str
    left_present: bool
    right_present: bool
    left_images: tuple[ImageRecord, ...]
    right_images: tuple[ImageRecord, ...]
    anomalies: tuple[AnomalyRecord, ...]

    @property
    def has_left(self) -> bool:
        return self.left_present

    @property
    def has_right(self) -> bool:
        return self.right_present


@dataclass(frozen=True)
class DatasetScan:
    root: Path
    subjects: tuple[SubjectScan, ...]

    @property
    def image_records(self) -> tuple[ImageRecord, ...]:
        return tuple(
            image
            for subject in self.subjects
            for image in (*subject.left_images, *subject.right_images)
        )

    @property
    def anomalies(self) -> tuple[AnomalyRecord, ...]:
        return tuple(
            anomaly for subject in self.subjects for anomaly in subject.anomalies
        )


def scan_dataset(dataset_root: Path) -> DatasetScan:
    root = dataset_root.expanduser().resolve()
    if not root.exists():
        raise FileNotFoundError(f"Dataset root does not exist: {root}")
    if not root.is_dir():
        raise NotADirectoryError(f"Dataset root is not a directory: {root}")

    subjects = tuple(scan_subject(path, root) for path in subject_dirs(root))
    return DatasetScan(root=root, subjects=subjects)


def scan_subject(subject_path: Path, dataset_root: Path) -> SubjectScan:
    subject_id = subject_path.name
    left_present, left_images, left_anomalies = scan_eye(subject_path, dataset_root, "L")
    right_present, right_images, right_anomalies = scan_eye(subject_path, dataset_root, "R")
    anomalies = [*left_anomalies, *right_anomalies]

    if not left_present and not right_present:
        anomalies.append(
            AnomalyRecord(
                subject_id=subject_id,
                eye="",
                image_path="",
                issue="missing_both_eyes",
            )
        )

    return SubjectScan(
        subject_id=subject_id,
        left_present=left_present,
        right_present=right_present,
        left_images=tuple(left_images),
        right_images=tuple(right_images),
        anomalies=tuple(anomalies),
    )


def scan_eye(
    subject_path: Path, dataset_root: Path, eye: str
) -> tuple[bool, list[ImageRecord], list[AnomalyRecord]]:
    eye_path = subject_path / eye
    if not eye_path.is_dir():
        return False, [], []

    images: list[ImageRecord] = []
    anomalies: list[AnomalyRecord] = []
    file_paths = sorted(
        (path for path in eye_path.iterdir() if path.is_file()),
        key=lambda path: path.name,
    )
    for file_path in file_paths:
        if file_path.suffix.lower() not in SUPPORTED_EXTENSIONS:
            anomalies.append(
                make_anomaly(subject_path, dataset_root, eye, file_path, "invalid_format")
            )
            continue

        try:
            images.append(read_image_record(subject_path, dataset_root, eye, file_path))
        except ZeroDimensionImage:
            anomalies.append(
                make_anomaly(subject_path, dataset_root, eye, file_path, "zero_dimension_image")
            )
        except OSError:
            anomalies.append(
                make_anomaly(subject_path, dataset_root, eye, file_path, "corrupted_image")
            )

    return bool(file_paths), images, anomalies


def read_image_record(
    subject_path: Path, dataset_root: Path, eye: str, file_path: Path
) -> ImageRecord:
    with Image.open(file_path) as image:
        image.load()
        width, height = image.size
        image_format = image.format or ""

    if width == 0 and height == 0:
        raise ZeroDimensionImage

    return ImageRecord(
        subject_id=subject_path.name,
        eye=eye,
        image_path=relative_image_path(file_path, dataset_root),
        width=width,
        height=height,
        format=image_format,
        file_size=file_path.stat().st_size,
    )


def make_anomaly(
    subject_path: Path, dataset_root: Path, eye: str, file_path: Path, issue: str
) -> AnomalyRecord:
    return AnomalyRecord(
        subject_id=subject_path.name,
        eye=eye,
        image_path=relative_image_path(file_path, dataset_root),
        issue=issue,
    )


def subject_dirs(dataset_root: Path) -> list[Path]:
    return sorted(
        (path for path in dataset_root.iterdir() if path.is_dir()),
        key=lambda path: path.name,
    )


def relative_image_path(file_path: Path, dataset_root: Path) -> str:
    return file_path.relative_to(dataset_root).as_posix()


def write_dataset_csv(path: Path, records: tuple[ImageRecord, ...]) -> None:
    ensure_parent(path)
    with path.open("w", newline="", encoding="utf-8") as csv_file:
        writer = csv.DictWriter(
            csv_file,
            fieldnames=[
                "subject_id",
                "eye",
                "image_path",
                "width",
                "height",
                "format",
                "file_size",
            ],
        )
        writer.writeheader()
        for record in records:
            writer.writerow(record.__dict__)


def write_anomalies_csv(path: Path, records: tuple[AnomalyRecord, ...]) -> None:
    ensure_parent(path)
    with path.open("w", newline="", encoding="utf-8") as csv_file:
        writer = csv.DictWriter(
            csv_file,
            fieldnames=["subject_id", "eye", "image_path", "issue"],
        )
        writer.writeheader()
        for record in records:
            writer.writerow(record.__dict__)


def ensure_parent(path: Path) -> None:
    path.expanduser().resolve().parent.mkdir(parents=True, exist_ok=True)


class ZeroDimensionImage(Exception):
    pass
